content.text:
{
  "primary_meaning": "Angels or heavenly/spiritual beings",
  "primary_basis": [
    "Revelation 1:20",
    "Job 38:7",
    "Isaiah 14:12-13",
    "Revelation 12:4"
  ],
  "alternatives": [
    {
      "meaning": "The people of God, saints, or Abraham's innumerable descendants",
      "basis": [
        "Genesis 15:5",
        "Genesis 22:17",
        "Genesis 37:9",
        "Daniel 12:3"
      ],
      "prominence": "common"
    },
    {
      "meaning": "Rulers, leaders, or authorities (including sometimes church leaders)",
      "basis": [
        "Genesis 37:9",
        "Numbers 24:17",
        "Revelation 1:20 (alternative pastoral reading)"
      ],
      "prominence": "common"
    },
    {
      "meaning": "Christ himself (especially as Morning Star)",
      "basis": [
        "Revelation 22:16",
        "2 Peter 1:19",
        "Numbers 24:17"
      ],
      "prominence": "common"
    },
    {
      "meaning": "Signs of cosmic upheaval, judgment, or divine order (often more literal celestial imagery with symbolic import)",
      "basis": [
        "Matthew 24:29",
        "Revelation 6:13",
        "Isaiah 13:10"
      ],
      "prominence": "common"
    }
  ],
  "has_settled_consensus": false,
  "confidence": "high",
  "notes": "Meanings are strongly context-dependent across narrative, prophetic, and apocalyptic texts; angelic symbolism is the most frequent single association in classic Christian exegesis of the term in plural form, especially Revelation and Job, but no exclusive monopoly exists."
}
